using System;
using System.Collections.Generic;
using System.Text;
namespace LordranEnemy {
// Independent read-only interpretation of SoloParamRepository and PARAM layout facts.
public class NpcDamage {
 public static readonly Dictionary<string,long> Slots=new Dictionary<string,long>{{"1.2.0",0x3c6b578L},{"1.2.1",0x3c6b598L},{"1.2.2",0x3c6b5b8L},{"1.2.3",0x3c6e5c8L},{"1.3.0",0x3c80158L},{"1.3.1",0x3c80158L},{"1.3.2",0x3c80158L},{"1.4.0",0x3c232e8L},{"1.4.1",0x3c232e8L},{"1.5.0",0x3c3b0d8L},{"1.6.0",0x3c4c348L},{"1.7.0",0x3c66d18L},{"1.8.0",0x3cf5788L},{"1.8.1",0x3cf5788L},{"1.9.0",0x3cf8bc8L},{"1.9.1",0x3cf8bc8L},{"2.0.0",0x3cf8bc8L},{"2.0.1",0x3cf8bc8L},{"2.2.0",0x3d81ee8L},{"2.2.3",0x3d81f08L},{"2.3.0",0x3d81f08L},{"2.4.0",0x3d81ee8L},{"2.5.0",0x3d81ee8L},{"2.6.0",0x3d81ee8L},{"2.6.1",0x3d81ee8L},{"2.6.2",0x3d81ee8L},{"2.7.0",0x3d85f58L},{"2.7.1",0x3d85f58L}};
 public int[] BaseStatus;long file;int count;Dictionary<int,long> rows;Dictionary<int,int> positions;
 public void Reset(){file=0;count=0;rows=null;positions=null;BaseStatus=null;}
 public static readonly string[] Labels={"Standard","Slash","Strike","Pierce","Magic","Fire","Lightning","Holy"};
 public static float[] Decode(byte[] bytes){if(bytes==null||bytes.Length!=32)throw new Exception("Invalid damage data size.");var result=new float[8];bool nonzero=false;for(int i=0;i<8;i++){float multiplier=BitConverter.ToSingle(bytes,i*4);if(float.IsNaN(multiplier)||float.IsInfinity(multiplier)||multiplier<0||multiplier>100)throw new Exception("Invalid damage multiplier.");nonzero|=multiplier>0;result[i]=(1-multiplier)*100;}if(!nonzero)throw new Exception("Damage data is empty.");return result;}
 public float[] Read(long slot,int npc,Func<long,int,byte[]> read){long repo=EnemyReader.Pointer(read,slot),cap=EnemyReader.Pointer(read,repo+0x238),inner=EnemyReader.Pointer(read,cap+0x80),param=EnemyReader.Pointer(read,inner+0x80);byte[] header=read(param,0x40);int size=BitConverter.ToInt32(read(param-0x10,4),0),n=BitConverter.ToUInt16(header,0xA);long name=BitConverter.ToInt64(header,0x10);if(n<=0||n>60000||size<0x40+n*24||size>64000000||name<0x40||name>size-13)throw new Exception("NPC parameter header unsupported.");if(Encoding.ASCII.GetString(read(param+name,13)).TrimEnd('\0')!="NPC_PARAM_ST")throw new Exception("Parameter is not NPC_PARAM_ST.");
 if(file!=param||count!=n||rows==null){Reset();byte[] table=read(param+0x40,n*24);var index=new Dictionary<int,long>();var rowPositions=new Dictionary<int,int>();for(int i=0;i<n;i++){int id=BitConverter.ToInt32(table,i*24);long offset=BitConverter.ToInt64(table,i*24+8);if(id<0||offset<0x40+n*24||offset>size-0x1E4||index.ContainsKey(id))throw new Exception("NPC row table failed validation.");index.Add(id,offset);rowPositions.Add(id,i);}if(!read(param,0x40).AsSpanEqual(header))throw new Exception("NPC parameter header changed.");file=param;count=n;rows=index;positions=rowPositions;}
 long row;if(!rows.TryGetValue(npc,out row))throw new Exception("Exact NPC parameter row not found.");byte[] entry=read(param+0x40+positions[npc]*24,24);if(BitConverter.ToInt32(entry,0)!=npc||BitConverter.ToInt64(entry,8)!=row||row>size-0x1E4)throw new Exception("Cached NPC row changed.");byte[] baseRow=read(param+row,0x1E4);float[] values=Decode(read(param+row+0x1A4,32));int[] offsets={0x108,0x10A,0x10C,0x10E,0x1E0,0x126,0x128};var statuses=new int[7];for(int i=0;i<7;i++)statuses[i]=BitConverter.ToUInt16(baseRow,offsets[i]);if(!read(param+0x40+positions[npc]*24,24).AsSpanEqual(entry))throw new Exception("NPC row changed during reading.");if(EnemyReader.Pointer(read,slot)!=repo||EnemyReader.Pointer(read,repo+0x238)!=cap||EnemyReader.Pointer(read,cap+0x80)!=inner||EnemyReader.Pointer(read,inner+0x80)!=param||!read(param,0x40).AsSpanEqual(header))throw new Exception("NPC parameters changed while reading.");BaseStatus=statuses;return values;}
}
static class ByteComparison {public static bool AsSpanEqual(this byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}}
}
